S.append(S2(c,B+' · 4','Khoảng trắng và kí tự đặc biệt',card('Quy tắc hiển thị',P('Nhiều dấu cách, xuống dòng trong mã HTML <b>chỉ hiện thành MỘT dấu cách</b>.','Muốn xuống dòng dùng <b>&lt;br&gt;</b> hoặc <b>&lt;p&gt;</b>.','Kí tự đặc biệt dùng <b>thực thể</b>: <code>&amp;lt;</code> (&lt;), <code>&amp;gt;</code> (&gt;), <code>&amp;amp;</code> (&amp;), <code>&amp;nbsp;</code> (dấu cách không ngắt).','Chú thích (không hiển thị): <code>&lt;!-- ghi chú --&gt;</code>.')),CODE('<p>A      B\n   C</p>\n<p>5 &lt; 7 &amp; 9 &gt; 2</p>\n<p>A&nbsp;&nbsp;&nbsp;B</p>\n<!-- Đây là chú thích -->',21)+BROWSER('<p>A      B\n   C</p><p>5 &lt; 7 &amp; 9 &gt; 2</p><p>A&nbsp;&nbsp;&nbsp;B</p>',h=180)))
S.append(S2(c,B+' · 5','Thẻ khối và thẻ nội tuyến',card('Hai loại hiển thị',P('<b>Khối</b> (block): <b>chiếm cả dòng</b>, xuống dòng trước và sau: h1–h6, p, div, ul, table, form…','<b>Nội tuyến</b> (inline): <b>chỉ chiếm vừa nội dung</b>, nằm cùng dòng: a, b, i, span, img…','<b>div</b>: khối chung để gộp phần tử; <b>span</b>: nội tuyến chung để định dạng một đoạn chữ.')),CODE('<div style="background:#BBDEFB">Khối div</div>\n<span style="background:#FFF59D">span 1</span>\n<span style="background:#FFF59D">span 2</span>',20)+BROWSER('<div style="background:#BBDEFB">Khối div (chiếm cả dòng)</div><span style="background:#FFF59D">span 1</span> <span style="background:#FFF59D">span 2</span> (cùng dòng)',h=130)+KEY('Khối <b>xuống dòng</b>, nội tuyến <b>cùng dòng</b>: kiến thức nền cho CSS và box model.')))
S.append(S2(c,B+' · 5','Thẻ ngữ nghĩa trong HTML5',card('Đặt tên theo vai trò',ul(['<b>&lt;header&gt;</b>: phần đầu trang (logo, tiêu đề).','<b>&lt;nav&gt;</b>: <b>điều hướng chính</b> (nhóm liên kết).','<b>&lt;main&gt;</b>: nội dung chính (mỗi trang một main).','<b>&lt;section&gt;</b>, <b>&lt;article&gt;</b>: mục / bài viết.','<b>&lt;aside&gt;</b>: nội dung phụ, thanh bên.','<b>&lt;footer&gt;</b>: chân trang (bản quyền, liên hệ).'],6)),svgbox(310,'<rect x="10" y="10" width="500" height="50" rx="8" fill="#BBDEFB" stroke="#1565C0" stroke-width="3"/><text x="260" y="43" text-anchor="middle" font-size="24" fill="#0B2545">header</text><rect x="10" y="68" width="500" height="44" rx="8" fill="#FFF9C4" stroke="#F9A825" stroke-width="3"/><text x="260" y="98" text-anchor="middle" font-size="24" fill="#0B2545">nav</text><rect x="10" y="120" width="340" height="130" rx="8" fill="#C8E6C9" stroke="#2E7D32" stroke-width="3"/><text x="180" y="195" text-anchor="middle" font-size="24" fill="#0B2545">main (section, article)</text><rect x="358" y="120" width="152" height="130" rx="8" fill="#E1BEE7" stroke="#6A1B9A" stroke-width="3"/><text x="434" y="195" text-anchor="middle" font-size="24" fill="#0B2545">aside</text><rect x="10" y="258" width="500" height="44" rx="8" fill="#FFCDD2" stroke="#C62828" stroke-width="3"/><text x="260" y="288" text-anchor="middle" font-size="24" fill="#0B2545">footer</text>')+KEY('Điều hướng chính của trang dùng <b>&lt;nav&gt;</b>; chân trang thường chứa <b>bản quyền, liên hệ</b>.')))
S.append(S2(c,B+' · 5','Thuộc tính id và class',card('Hai thuộc tính để “đặt tên” phần tử',P('<b>id</b>: tên <b>duy nhất</b> trong cả trang (như số căn cước). Dùng cho CSS, JavaScript và <b>liên kết nội trang</b> <code>#id</code>.','<b>class</b>: tên <b>nhóm</b>; nhiều phần tử có thể <b>cùng class</b>, một phần tử có thể có <b>nhiều class</b> (cách nhau dấu cách).','Vì id phải duy nhất nên <b>không đặt hai phần tử cùng id</b>: trình duyệt không biết chọn phần tử nào.')),CODE('<h2 id="gioithieu">Giới thiệu</h2>\n<p class="note big">Ghi chú 1</p>\n<p class="note">Ghi chú 2</p>\n\n<a href="#gioithieu">Về đầu mục</a>',20)+KEY('<b>id</b>: duy nhất; <b>class</b>: dùng chung. Liên kết nội trang <b>href="#gioithieu"</b> nhảy tới phần tử có <b>id="gioithieu"</b>.')))
S.append(SELF(c,B+' · 6','Tự kiểm tra: vị trí các thẻ','Dòng nào của đoạn mã dưới đây đặt sai vị trí?','<html>\n<head>\n  <title>Trang chủ</title>\n  <h1>CLB Tin học</h1>\n  <link rel="stylesheet" href="s.css">\n</head>\n<body>\n  <p>Chào mừng</p>\n</body>\n</html>',P('<b>title</b> và <b>link</b> đúng chỗ ở <b>head</b>; <b>p</b> đúng chỗ ở <b>body</b>.','<b>&lt;h1&gt; nằm trong &lt;head&gt;</b> là sai: head chứa <b>thông tin về tài liệu</b>, còn nội dung hiển thị như h1, p phải ở <b>body</b>.'),19))
S.append(SELF(c,B+' · 6','Tự kiểm tra: thẻ cho chỉ số trên, dưới và xuống dòng','Viết HTML hiển thị “H₂O”, “x²” và một đoạn có hai dòng không tạo đoạn mới.','<p>H<sub>2</sub>O và x<sup>2</sup></p>\n<p>Dòng 1<br>Dòng 2</p>',P('Chỉ số dưới: <b>sub</b>; chỉ số trên: <b>sup</b>; xuống dòng trong cùng đoạn: <b>br</b> (thẻ rỗng).')+BROWSER('<p>H<sub>2</sub>O và x<sup>2</sup></p><p>Dòng 1<br>Dòng 2</p>',h=140,lab='Kết quả dựng thật'),21))
S.append(SELF(c,B+' · 6','Tự kiểm tra (HSG): đúng hay sai?','Xét các phát biểu: (a) &lt;a href="#gt"&gt; nhảy tới phần tử có id="gt" trong cùng trang. (b) Hai phần tử trong cùng trang nên có id khác nhau. (c) Liên kết ra website khác chỉ được dùng đường dẫn tương đối. (d) HTML là ngôn ngữ lập trình có vòng lặp và rẽ nhánh.','<a href="#gt">Tới mục</a>\n<h2 id="gt">Giới thiệu</h2>',P('(a) <b>Đúng</b>: <b>#id</b> là liên kết nội trang.','(b) <b>Đúng</b>: id phải duy nhất.','(c) <b>Sai</b>: liên kết ra website khác dùng <b>đường dẫn tuyệt đối</b> (có https://).','(d) <b>Sai</b>: HTML là ngôn ngữ <b>đánh dấu</b> siêu văn bản, không có vòng lặp, rẽ nhánh.'),20))
S.append(SELF(c,B+' · 6','Tự kiểm tra (HSG): mã trạng thái HTTP','Trình duyệt gửi yêu cầu và nhận mã 404. Điều đó có nghĩa gì? Phân biệt với 200, 401, 500.','GET /baitap/khongco.html  → 404',P('<b>404 Not Found</b>: máy chủ <b>hoạt động bình thường nhưng không tìm thấy</b> tài nguyên được yêu cầu (địa chỉ sai hoặc trang bị xoá).','<b>200</b>: thành công. <b>401</b>: cần <b>xác thực</b> (chưa đăng nhập). <b>500</b>: lỗi <b>nội bộ</b> của máy chủ.')+KEY('Nhóm <b>4xx</b>: lỗi từ phía yêu cầu; nhóm <b>5xx</b>: lỗi phía máy chủ.'),21))
S+=END(c,B,['Web là <b>dịch vụ trên Internet</b>; trình duyệt gửi yêu cầu, máy chủ web trả phản hồi.','URL gồm <b>giao thức, tên miền, đường dẫn, truy vấn, mỏ neo</b>; <b>DNS</b> đổi tên miền thành IP.','<b>HTTPS</b> mã hoá; <b>404</b> = không tìm thấy; <b>500</b> = lỗi máy chủ.','HTML (cấu trúc) – CSS (trình bày) – JavaScript (hành vi).','<b>head</b> chứa thông tin (title ở thanh tab); <b>body</b> chứa nội dung hiển thị.','<b>id</b> duy nhất; <b>class</b> dùng chung; thuộc tính chỉ ở <b>thẻ mở</b>.'],[('Tên miền → IP','DNS'),('Điều hướng chính','nav'),('Xuống dòng','br'),('Neo trong trang','href="#id"')],'Đặt h1 trong head; viết thuộc tính ở thẻ đóng; trùng id; lồng thẻ sai thứ tự.',['Nhiều khoảng trắng trong HTML chỉ thành <b>một</b> dấu cách.','<code>&lt;b&gt;&lt;i&gt;…&lt;/b&gt;&lt;/i&gt;</code> là lồng sai.','<b>Chân trang (footer)</b>: bản quyền, liên hệ.','Liên kết ra ngoài: <b>đường dẫn tuyệt đối</b>.'],['<b>Thẻ meta viewport</b> cho điện thoại.','<b>Open Graph</b> khi chia sẻ.','<b>Accessibility</b>: thuộc tính alt, thẻ ngữ nghĩa.'],
 [('Thẻ title hiển thị ở đâu?',),('Thẻ nào chứa nội dung hiển thị của trang?',),('Cặp thẻ viết H₂O?',),('Mã 404 nghĩa là gì?',),('Thẻ nào dùng cho điều hướng chính?',)],
 [('Trên <b>thanh tab</b> của trình duyệt.',),('<b>body</b>.',),('H<b>&lt;sub&gt;</b>2<b>&lt;/sub&gt;</b>O.',),('Không tìm thấy tài nguyên.',),('<b>&lt;nav&gt;</b>.',)],
 [('Mức 1. Viết trang HTML có tiêu đề h1 “Lớp 12A1”, một đoạn giới thiệu và một đường kẻ ngang.',),('Mức 1. Viết đoạn văn có chữ “Tin học” đậm, “Python” nghiêng.',),('Mức 2. Viết bố cục có header, nav, main, aside, footer đúng ngữ nghĩa.',),('Mức 2. Tạo mục lục: ba liên kết nhảy tới ba tiêu đề h2 trong cùng trang.',),('Mức 3 (HSG). Phát hiện 3 lỗi trong đoạn: <code>&lt;html&gt;&lt;body&gt;&lt;h1&gt;A&lt;/h1&gt;&lt;p id="x"&gt;B&lt;b&gt;C&lt;/p&gt;&lt;/b&gt;&lt;p id="x"&gt;D&lt;/p&gt;&lt;/body&gt;&lt;/html&gt;</code>.',),('Mức 3 (HSG). Giải thích vì sao khi gõ tinhoc.edu.vn trình duyệt có thể gửi nhiều yêu cầu HTTP, và vai trò của DNS.',)],
 [('Khung: h1, p, hr.',),('<code>&lt;b&gt;Tin học&lt;/b&gt;, &lt;i&gt;Python&lt;/i&gt;</code>.',),('<code>&lt;header&gt;&lt;nav&gt;&lt;main&gt;&lt;aside&gt;&lt;footer&gt;</code>.',),('<code>&lt;a href="#m1"&gt;</code> … <code>&lt;h2 id="m1"&gt;</code>.',),('Lỗi: thiếu DOCTYPE/head; <b>lồng sai b và p</b>; <b>trùng id="x"</b>.',),('DNS trả IP; trình duyệt xin HTML rồi xin thêm CSS, ảnh, script.',)],hper=2)
